mapper.update:
UPDATE wa_group_profile
SET current_invite_id = CASE
      WHEN #{observedAt} >= COALESCE(current_invite_observed_at, 0)
        THEN #{inviteId}
      ELSE current_invite_id
    END,
    updated_at = CASE
      WHEN #{observedAt} >= COALESCE(current_invite_observed_at, 0)
        THEN GREATEST(updated_at, #{now})
      ELSE updated_at
    END,
    current_invite_observed_at = GREATEST(
      COALESCE(current_invite_observed_at, 0), #{observedAt}
    )
WHERE tenant_id = #{tenantId}
  AND group_id = #{groupId}

UPDATE group_link
SET group_id = #{groupId},
    group_invite_id = #{inviteId}
WHERE tenant_id = #{tenantId}
  AND id = #{groupLinkId}
  AND deleted_at IS NULL

UPDATE group_link
SET group_id = #{groupId}
WHERE tenant_id = #{tenantId}
  AND id = #{groupLinkId}
  AND deleted_at IS NULL

UPDATE group_link
SET group_invite_id = #{inviteId}
WHERE tenant_id = #{tenantId}
  AND id = #{groupLinkId}

UPDATE wa_group_profile
SET health_status = #{health.healthStatus},
    banned = #{health.banned},
    checked_member_count = COALESCE(
      #{health.currentCount}, checked_member_count
    ),
    last_checked_at = #{health.lastCheckAt},
    last_error_code = LEFT(#{health.lastHealthError}, 64),
    failure_count = #{health.healthFailureCount},
    updated_at = #{now}
WHERE tenant_id = #{tenantId}
  AND group_id = #{groupId}
